/* Load: the whole content fades in over 500ms. */
@media (prefers-reduced-motion: no-preference) {
  .cfs-hero-in {
    animation: cfs-hero-fade 500ms ease both;
  }
  /* The active pillar's dot pulses every two seconds. */
  .cfs-hero-dot-active {
    animation: cfs-hero-pulse 2s ease-in-out infinite;
  }
}

@keyframes cfs-hero-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes cfs-hero-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(0.7); }
}

/* Scrubbed while the hero leaves the window: the photo grows 1 → 1.05 over the whole exit,
   the pillars fade out over the first half (half a screen of scrolling). */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .cfs-hero {
      view-timeline-name: --cfs-hero;
    }
    .cfs-hero-media,
    .cfs-hero-pillars {
      animation-timing-function: linear;
      animation-fill-mode: both;
      animation-timeline: --cfs-hero;
    }
    .cfs-hero-media {
      animation-name: cfs-hero-grow;
      animation-range: exit 0% exit 100%;
    }
    .cfs-hero-pillars {
      animation-name: cfs-hero-out;
      animation-range: exit 0% exit 50%;
    }
  }
}

@keyframes cfs-hero-grow {
  from { transform: scale(1); }
  to { transform: scale(1.05); }
}
@keyframes cfs-hero-out {
  from { opacity: 1; }
  to { opacity: 0; }
}

import type { ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./cfs-hero.css";

export interface CfsHeroPillar {
  /** short monospace label, e.g. "Build small" */
  label: string;
  /** one or two sentences under it */
  text: string;
}

export interface CfsHeroProps {
  /** the big statement (wraps to about three lines on wide screens) */
  title: string;
  /** up to three pillars shown under the title */
  pillars: CfsHeroPillar[];
  /** which pillar's dot is filled (and pulses); default 0 */
  activeIndex?: number;
  /** the background photo or video; covers the hero. Empty: a placeholder */
  media?: ReactNode;
  className?: string;
}

/** Full-window photo hero with a light statement and three dotted pillars. */
export function CfsHero({ title, pillars, activeIndex = 0, media, className }: CfsHeroProps) {
  return (
    <section className={cn("cfs-hero dark relative flex h-svh min-h-[40rem] flex-col overflow-clip bg-background text-foreground", className)}>
      <div
        className={cn(
          "cfs-hero-media absolute inset-0 [&>img]:size-full [&>img]:object-cover [&>video]:size-full [&>video]:object-cover",
          !media && "bg-muted",
        )}
      >
        {media}
      </div>
      {/* a soft scrim at the bottom keeps the white type readable on any photo */}
      <div aria-hidden className="absolute inset-0 bg-gradient-to-t from-background/60 via-background/10 to-transparent" />

      <div className="cfs-hero-in relative mx-auto mt-auto w-full max-w-page px-gutter pb-10 lg:pb-[3.25rem]">
        <h1 className="max-w-[13em] font-display text-[clamp(2.125rem,4.383vw,3.945rem)] leading-[1.2] font-[350]">{title}</h1>

        <ul className="cfs-hero-pillars mt-[2.875rem] grid gap-y-9 lg:mt-[3.25rem] lg:grid-cols-4 lg:gap-x-5">
          {pillars.map((pillar, i) => (
            <li key={pillar.label}>
              <p className="flex items-center gap-[7px] font-mono text-sm leading-[1.2]">
                <span
                  aria-hidden
                  className={cn(
                    "size-3 shrink-0 rounded-full border border-primary",
                    i === activeIndex ? "cfs-hero-dot-active bg-primary" : "bg-transparent",
                  )}
                />
                {pillar.label}
              </p>
              <p className="mt-3 max-w-[18.75rem] text-sm leading-[1.5] lg:mt-[1.375rem]">{pillar.text}</p>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
